import urllib.request, concurrent.futures, pathlib
assets={'architecture':'https://images.unsplash.com/photo-1600210492486-724fe5c67fb0?w=900&auto=format&fit=crop&q=85','nature':'https://images.unsplash.com/photo-1448375240586-882707db888b?w=900&auto=format&fit=crop&q=85','art':'https://images.unsplash.com/photo-1578749556568-bc2c40e68b61?w=900&auto=format&fit=crop&q=85','avatar':'https://images.unsplash.com/photo-1534528741775-53994a69daeb?w=80&h=80&fit=crop&crop=faces'}
pathlib.Path('public/images').mkdir(parents=True,exist_ok=True)
def save(item):
 name,url=item
 try:
  r=urllib.request.urlopen(url,timeout=25)
  data=r.read()
  pathlib.Path('public/images/'+name+'.jpg').write_bytes(data)
  return name,r.status,len(data)
 except Exception as e:return name,str(e)
for r in concurrent.futures.ThreadPoolExecutor().map(save,assets.items()):print(r)
PY"

